  const texto = candidato && candidato.content && (candidato.content.parts || []).map(p => p.text || '').join('');
  if (!texto) {
    const razon = (candidato && candidato.finishReason) || (r.body && r.body.promptFeedback && r.body.promptFeedback.blockReason) || 'desconocida';
    throw new Error('El LLM no devolvió texto (razón: ' + razon + ')');
