let texto = null;
try {
  texto = extraerTexto(r);
  return [{ json: { valido: true, clasificacion: validar(texto), error: null, respuesta_llm: texto } }];
} catch (e) {
  return [{ json: { valido: false, clasificacion: null, error: e.message, respuesta_llm: texto } }];
}

// El LLM falló dos veces: la solicitud se guardará sin clasificar y marcada para revisión manual.
return [{
  json: {
    valido: false,
    clasificacion: null,
    error: $input.first().json.error,
    error_intento_1: $('Preparar reintento').first().json.error_intento_1,
  },
}];

// Punto de encuentro de los tres caminos: válido al 1er intento, al 2º, o revisión manual.
const r = $input.first().json;
const intentos = $('Gemini intento 2').isExecuted ? 2 : 1;
return [{ json: { llm_ok: r.valido === true, clasificacion: r.clasificacion, error_llm: r.error || null, intentos } }];

// Relaciona correo y producto con la BD y arma el cuerpo de POST /solicitudes.
const cfg = $('Config y validar entrada').first().json;
const cls = $('Clasificación final').first().json;
const c = cls.clasificacion || {};

const respCliente = $('Buscar cliente').first().json;
if (respCliente.statusCode >= 500) throw new Error('La API falló al buscar el cliente (HTTP ' + respCliente.statusCode + ')');
const cliente = respCliente.statusCode === 200 ? respCliente.body : null;

let producto = null, puntaje = null;
if ($('Buscar producto').isExecuted) {
  const respProducto = $('Buscar producto').first().json;
  if (respProducto.statusCode >= 500) throw new Error('La API falló al buscar el producto (HTTP ' + respProducto.statusCode + ')');
  if (respProducto.statusCode === 200) { producto = respProducto.body.producto; puntaje = respProducto.body.puntaje; }
}

const motivos = [];
if (!cls.llm_ok) motivos.push('llm_invalido');
if (!cliente) motivos.push('cliente_no_registrado');

return [{
  json: {
    body: {
      cliente_id: cliente ? cliente.id : null,
      email_remitente: cfg.entrada.cliente_email,
      producto_id: producto ? producto.id : null,
      producto_texto: c.producto || null,
      tipo: c.tipo || null,
      cantidad: c.cantidad ?? null,
      urgencia: c.urgencia || null,
      mensaje: cfg.entrada.mensaje,
      resumen: c.resumen || null,
      requiere_revision: motivos.length > 0,
      motivo_revision: motivos.length ? motivos.join(',') : null,
    },
    cliente,
    producto,
    puntaje_producto: puntaje,
  },
}];

// Decide si hay que notificar y por qué. Condiciones del enunciado: queja, urgencia alta,
// pedido sin stock. Adicional: revisión manual (LLM falló o el correo no es de un cliente).
const s = $input.first().json.body;          // respuesta de POST /solicitudes
const armado = $('Armar solicitud').first().json;
const cls = $('Clasificación final').first().json;

const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const MOTIVOS = { llm_invalido: 'el LLM no devolvió una clasificación válida en 2 intentos', cliente_no_registrado: 'el correo no corresponde a ningún cliente registrado' };

const alertas = [];
if (s.tipo === 'queja') alertas.push({ condicion: 'queja', detalle: 'La solicitud es una queja' });
if (s.urgencia === 'alta') alertas.push({ condicion: 'urgencia_alta', detalle: 'Urgencia alta' });
if (s.sin_stock) alertas.push({ condicion: 'sin_stock', detalle: `Piden ${s.cantidad} und. de ${s.producto_nombre} y hay ${s.stock_disponible} en stock (faltan ${s.cantidad - s.stock_disponible})` });
if (s.requiere_revision) alertas.push({ condicion: 'revision_manual', detalle: 'Revisión manual: ' + (s.motivo_revision || '').split(',').map(m => MOTIVOS[m] || m).join('; ') });

const ICONOS = { queja: '😠', urgencia_alta: '⏰', sin_stock: '📦', revision_manual: '👀' };
const texto = [
  `🚨 <b>Solicitud #${s.id} requiere atención</b>`,
  '',
  ...alertas.map(a => `${ICONOS[a.condicion]} <b>${esc(a.condicion)}</b>: ${esc(a.detalle)}`),
  '',
  `<b>Cliente:</b> ${esc(s.cliente_nombre || 'No registrado')} (${esc(s.email_remitente)})`,
  `<b>Tipo:</b> ${esc(s.tipo || 'sin clasificar')} · <b>Urgencia:</b> ${esc(s.urgencia || '-')}`,
  `<b>Producto:</b> ${esc(s.producto_nombre || s.producto_texto || '-')}${s.cantidad ? ' × ' + s.cantidad : ''}`,
  `<b>Resumen:</b> ${esc(s.resumen || '-')}`,
  `<b>Mensaje:</b> <i>${esc(s.mensaje.slice(0, 500))}</i>`,
].join('\n');

return [{
  json: {
    requiere_alerta: alertas.length > 0,
    texto_alerta: texto,
    respuesta: {
      id: s.id,
      clasificacion: cls.clasificacion,
      cliente: s.cliente_id ? { id: s.cliente_id, nombre: s.cliente_nombre } : null,
      producto_catalogo: armado.producto ? { id: armado.producto.id, nombre: armado.producto.nombre, stock: armado.producto.stock } : null,
      estado: s.estado,
      sin_stock: s.sin_stock,
      requiere_revision: s.requiere_revision,
      motivo_revision: s.motivo_revision,
      intentos_llm: cls.intentos,
      alertas,
    },
  },
}];

// Agrega a la respuesta si la notificación salió (un fallo de Telegram no detiene el flujo).
const base = $('Evaluar alertas').first().json;
let notificacion = { requerida: base.requiere_alerta, enviada: false, error: null };
if (base.requiere_alerta && $('Enviar alerta').isExecuted) {
  const t = $('Enviar alerta').first().json;
  notificacion.enviada = !t.error && !!(t.ok !== false && (t.message_id || t.result || t.chat));
  if (t.error) notificacion.error = String(t.error.message || t.error).slice(0, 200);
}
return [{ json: { ...base.respuesta, notificacion } }];

// Cualquier fallo técnico (API caída, error inesperado) termina aquí: se avisa y se responde
// con un JSON claro en vez de dejar el webhook colgado.
const anterior = $prevNode.name;
const j = $input.first().json;
let detalle = j.error ? (j.error.message || JSON.stringify(j.error)) : '';
if (!detalle && j.statusCode) detalle = `HTTP ${j.statusCode}: ${JSON.stringify(j.body).slice(0, 300)}`;
let entrada = {};
try { entrada = $('Config y validar entrada').first().json.entrada; } catch (e) {}
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{
  json: {
    status: 502,
    cuerpo: { error: 'error_procesando', mensaje: 'No se pudo registrar la solicitud. El equipo técnico fue notificado.', etapa: anterior, detalle: String(detalle).slice(0, 300) },
    texto_alerta: `🛠 <b>Error técnico en el flujo de solicitudes</b>\n<b>Etapa:</b> ${esc(anterior)}\n<b>Detalle:</b> ${esc(String(detalle).slice(0, 300))}\n<b>Remitente:</b> ${esc(entrada.cliente_email)}\n<b>Mensaje:</b> <i>${esc((entrada.mensaje || '').slice(0, 300))}</i>`,
  },
}];
